-- Inisialisasi database Website Kecamatan (impor via phpMyAdmin).
-- Dihasilkan otomatis oleh scripts/db-export-sql.mjs.
-- Target: MySQL 5.7+ / MariaDB 10.2+ (utf8mb4).
-- Pilih database tujuan lebih dulu, lalu Import file ini.
-- Semua seed memakai INSERT IGNORE: aman diimpor ulang, data yang sudah
-- diubah lewat panel admin tidak akan tertimpa.

SET NAMES utf8mb4;

-- =========== SKEMA ===========
CREATE TABLE IF NOT EXISTS site_settings (
  id INT PRIMARY KEY,
  data JSON NOT NULL,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
    ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS berita (
  slug VARCHAR(80) PRIMARY KEY,
  title VARCHAR(255) NOT NULL,
  date VARCHAR(20) NOT NULL,
  category VARCHAR(100) NOT NULL DEFAULT 'Umum',
  excerpt TEXT NOT NULL,
  image VARCHAR(255) NULL,
  image_alt VARCHAR(255) NULL,
  author VARCHAR(150) NOT NULL DEFAULT 'Pemerintah Kecamatan Jenar',
  body MEDIUMTEXT NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
    ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS admin_credentials (
  id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  username VARCHAR(150) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  role VARCHAR(20) NOT NULL DEFAULT 'admin',
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
    ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uniq_admin_username (username)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =========== MIGRASI (database versi lama) ===========
-- Migrasi: kolom `role` (dilewati bila sudah ada).
SET @m := (SELECT IF(COUNT(*) = 0, 'ALTER TABLE admin_credentials ADD COLUMN role VARCHAR(20) NOT NULL DEFAULT ''admin''', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'admin_credentials' AND COLUMN_NAME = 'role');
PREPARE s FROM @m; EXECUTE s; DEALLOCATE PREPARE s;

-- Migrasi: `id` AUTO_INCREMENT (dilewati bila sudah ada).
SET @m := (SELECT IF(COUNT(*) = 0, 'ALTER TABLE admin_credentials MODIFY id INT NOT NULL AUTO_INCREMENT', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'admin_credentials' AND COLUMN_NAME = 'id' AND EXTRA LIKE '%auto_increment%');
PREPARE s FROM @m; EXECUTE s; DEALLOCATE PREPARE s;

-- Migrasi: indeks unik username (dilewati bila sudah ada).
SET @m := (SELECT IF(COUNT(*) = 0, 'ALTER TABLE admin_credentials ADD UNIQUE KEY uniq_admin_username (username)', 'DO 0') FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'admin_credentials' AND INDEX_NAME = 'uniq_admin_username');
PREPARE s FROM @m; EXECUTE s; DEALLOCATE PREPARE s;

