INSERT IGNORE INTO site_settings (id, data) VALUES (1, '{\"site\":{\"name\":\"Kecamatan Jenar\",\"legalName\":\"Pemerintah Kecamatan Jenar\",\"tagline\":\"Kab. Sragen, Jawa Tengah\",\"region\":\"Kabupaten Sragen, Jawa Tengah\",\"slogan\":\"Pelayanan Umum Gratis\",\"url\":\"https://jenar.sragen.go.id\",\"email\":\"kec.jenar.sragen@gmail.com\",\"phone\":\"0813-9301-1650\",\"phoneIntl\":\"+6281393011650\",\"address\":\"Jl. Pungkruk – Tanon, Km. 1, Dk. Jenar RT 3, Jenar, Sragen, Jawa Tengah 57281\",\"links\":{\"aduan\":\"http://bit.ly/PengaduanJenar\",\"skm\":\"https://bit.ly/SKMDesaJenar\",\"spak\":\"https://bit.ly/SPAKDesaJenar\"},\"social\":{\"facebook\":\"#\",\"instagram\":\"#\",\"youtube\":\"#\"}},\"jamPelayanan\":[{\"day\":\"Senin – Kamis\",\"time\":\"07.30 – 16.00 WIB\",\"rest\":\"Istirahat 12.00 – 13.00\"},{\"day\":\"Jum\'at\",\"time\":\"07.15 – 14.30 WIB\",\"rest\":\"Istirahat 11.30 – 12.30\"},{\"day\":\"Sabtu – Minggu\",\"time\":\"Libur\",\"rest\":null}],\"externalLinks\":[{\"label\":\"Survei Kepuasan Masyarakat\",\"url\":\"https://bit.ly/SKMDesaJenar\"},{\"label\":\"Survei Anti Korupsi\",\"url\":\"https://bit.ly/SPAKDesaJenar\"}],\"tentang\":{\"paragraf1\":\"Kecamatan Jenar merupakan salah satu dari 20 kecamatan di wilayah Kabupaten Sragen, Provinsi Jawa Tengah, dan membawahi 7 desa.\",\"paragraf2\":\"Pemerintah Kecamatan Jenar berkomitmen memberikan pelayanan publik yang transparan, cepat, dan bebas korupsi — serta mendorong keterbukaan informasi bagi seluruh warga masyarakat.\",\"quickFacts\":[{\"value\":\"26.550\",\"label\":\"Jumlah Penduduk\"},{\"value\":\"7\",\"label\":\"Desa di Kecamatan\"},{\"value\":\"Gratis\",\"label\":\"Biaya Pelayanan\"}]},\"hero\":{\"eyebrow\":\"Website Resmi\",\"subtitle\":\"Kabupaten Sragen, Jawa Tengah\",\"description\":\"Portal layanan publik kecamatan yang transparan, melayani, dan bebas korupsi. Akses informasi, layanan administrasi, dan pengaduan masyarakat dalam satu tempat.\",\"slides\":[{\"img\":\"/images/hero/slide-1.jpeg\",\"alt\":\"Hamparan sawah dan perbukitan di Kecamatan Jenar\"},{\"img\":\"/images/hero/slide-2.jpeg\",\"alt\":\"Suasana senja di persawahan wilayah Kecamatan Jenar\"},{\"img\":\"/images/hero/slide-3.jpg\",\"alt\":\"Sawah di Kecamatan Jenar\"}]},\"layanan\":[{\"title\":\"SOP Pelayanan Administrasi\",\"desc\":\"Standar operasional prosedur pelayanan administrasi bagi masyarakat.\",\"href\":\"/layanan#sop\",\"icon\":\"M9 5H7a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-2M9 5a2 2 0 0 0 2 2h2a2 2 0 0 0 2-2M9 5a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2m-6 9 2 2 4-4\"},{\"title\":\"Pelayanan & Persyaratan\",\"desc\":\"Jenis pelayanan beserta berkas dan persyaratan yang diperlukan.\",\"href\":\"/layanan#persyaratan\",\"icon\":\"M9 12h6m-6 4h4m2 5H7a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5.6a1 1 0 0 1 .7.3l5.4 5.4a1 1 0 0 1 .3.7V19a2 2 0 0 1-2 2Z\"},{\"title\":\"Maklumat Pelayanan\",\"desc\":\"Pernyataan komitmen pemerintah kecamatan atas mutu pelayanan publik.\",\"href\":\"/layanan#maklumat\",\"icon\":\"M3 11 21 6v12L3 13v-2Zm8.6 5.8a3 3 0 1 1-5.8-1.6\"},{\"title\":\"Layanan Pengaduan\",\"desc\":\"Sampaikan keluhan dan aspirasi terkait pelayanan kecamatan secara online.\",\"href\":\"/pengaduan\",\"icon\":\"M8 10h8M8 14h5m-9 6 3.5-3H18a2 2 0 0 0 2-2V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v14Z\"},{\"title\":\"Survei Kepuasan Masyarakat\",\"desc\":\"Berikan penilaian Anda terhadap kualitas pelayanan Kecamatan Jenar.\",\"href\":\"https://bit.ly/SKMDesaJenar\",\"icon\":\"M11.5 3.5a.6.6 0 0 1 1 0l2.3 4.6 5.1.7a.6.6 0 0 1 .3 1l-3.7 3.6.9 5.1a.6.6 0 0 1-.9.6L12 17.3l-4.5 2.4a.6.6 0 0 1-.9-.6l.9-5.1-3.7-3.6a.6.6 0 0 1 .3-1l5.1-.7 2.3-4.6Z\"},{\"title\":\"Pengadaan Barang & Jasa\",\"desc\":\"Informasi pengadaan barang dan jasa di lingkungan Kecamatan Jenar.\",\"href\":\"/layanan#pengadaan\",\"icon\":\"M20 7 12 3 4 7m16 0-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4\"}],\"perangkat\":[{\"name\":\"\",\"position\":\"Camat\",\"featured\":true,\"photo\":\"\"},{\"name\":\"\",\"position\":\"Sekretaris Kecamatan\",\"featured\":false,\"photo\":\"\"},{\"name\":\"\",\"position\":\"Kasubbag Umum & Kepegawaian\",\"featured\":false,\"photo\":\"\"},{\"name\":\"\",\"position\":\"Kasubbag Perencanaan & Keuangan\",\"featured\":false,\"photo\":\"\"},{\"name\":\"\",\"position\":\"Kasi Pemerintahan\",\"featured\":false,\"photo\":\"\"},{\"name\":\"\",\"position\":\"Kasi Ketenteraman & Ketertiban Umum\",\"featured\":false,\"photo\":\"\"},{\"name\":\"\",\"position\":\"Kasi Pemberdayaan Masyarakat\",\"featured\":false,\"photo\":\"\"},{\"name\":\"\",\"position\":\"Kasi Pelayanan Umum\",\"featured\":false,\"photo\":\"\"}],\"statistik\":{\"total\":26550,\"laki\":13150,\"perempuan\":13400,\"petaQuery\":\"Kantor Kecamatan Jenar, Jenar, Sragen, Jawa Tengah 57281\"},\"profil\":{\"visi\":\"Terwujudnya Kecamatan Jenar yang maju, mandiri, dan sejahtera melalui pelayanan publik yang prima, transparan, dan partisipatif.\",\"misi\":[\"Meningkatkan kualitas pelayanan administrasi dan publik yang cepat, mudah, serta bebas biaya bagi seluruh warga.\",\"Mewujudkan tata kelola pemerintahan kecamatan yang transparan, akuntabel, dan partisipatif.\",\"Mengoordinasikan penyelenggaraan pemerintahan dan pembangunan di seluruh desa dalam wilayah kecamatan.\",\"Memberdayakan ekonomi masyarakat melalui UMKM, pertanian, dan potensi lokal wilayah.\",\"Meningkatkan kualitas sumber daya manusia di bidang pendidikan, kesehatan, dan sosial keagamaan.\"],\"nilai\":[{\"title\":\"Transparan\",\"description\":\"Keterbukaan informasi anggaran, program, dan pelayanan kepada masyarakat.\",\"icon\":\"M2.5 12S6 5 12 5s9.5 7 9.5 7-3.5 7-9.5 7-9.5-7-9.5-7Z M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z\"},{\"title\":\"Melayani\",\"description\":\"Pelayanan umum gratis, cepat, dan ramah untuk seluruh warga wilayah kecamatan.\",\"icon\":\"M12 21c4.97-3.06 8-6.5 8-10a4 4 0 0 0-8-1 4 4 0 0 0-8 1c0 3.5 3.03 6.94 8 10Z\"},{\"title\":\"Amanah\",\"description\":\"Pengelolaan sumber daya dan aset daerah secara bertanggung jawab dan akuntabel.\",\"icon\":\"M12 3l7 3v5c0 4.5-3 8.5-7 10-4-1.5-7-5.5-7-10V6l7-3Z M9.5 12l1.8 1.8L15 10\"}],\"tupoksi\":[{\"jabatan\":\"Camat\",\"ringkasan\":\"Memimpin penyelenggaraan urusan pemerintahan umum di wilayah kecamatan serta melaksanakan kewenangan yang dilimpahkan oleh Bupati.\",\"tugas\":[\"Menyelenggarakan urusan pemerintahan umum di tingkat kecamatan.\",\"Mengoordinasikan kegiatan pemberdayaan masyarakat serta ketenteraman dan ketertiban umum.\",\"Membina dan mengawasi penyelenggaraan pemerintahan desa.\",\"Mengoordinasikan penyelenggaraan pelayanan publik di wilayah kecamatan.\"]},{\"jabatan\":\"Sekretaris Kecamatan\",\"ringkasan\":\"Membantu Camat dalam bidang administrasi dan memimpin penyelenggaraan kesekretariatan kecamatan.\",\"tugas\":[\"Mengoordinasikan tugas dan fungsi subbagian serta seksi di kecamatan.\",\"Menyusun rencana kerja, anggaran, dan laporan penyelenggaraan pemerintahan kecamatan.\",\"Menata administrasi umum, aset, dan kearsipan kecamatan.\",\"Melaksanakan urusan ketatausahaan dan surat-menyurat.\"]},{\"jabatan\":\"Kasubbag Perencanaan & Keuangan\",\"ringkasan\":\"Melaksanakan penyusunan perencanaan program serta pengelolaan administrasi keuangan kecamatan.\",\"tugas\":[\"Menyusun rencana kerja, program, dan bahan penyusunan anggaran kecamatan.\",\"Mengelola administrasi keuangan, pembukuan, serta verifikasi belanja.\",\"Menyusun laporan pertanggungjawaban keuangan dan capaian kinerja.\"]},{\"jabatan\":\"Kasubbag Umum & Kepegawaian\",\"ringkasan\":\"Melaksanakan urusan ketatausahaan, rumah tangga, sarana prasarana, dan administrasi kepegawaian.\",\"tugas\":[\"Mengelola inventaris, sarana prasarana, dan administrasi umum.\",\"Melaksanakan pelayanan administrasi kepegawaian aparatur kecamatan.\",\"Menata kearsipan serta melayani kebutuhan tata usaha perkantoran.\"]},{\"jabatan\":\"Kasi Pemerintahan\",\"ringkasan\":\"Melaksanakan koordinasi penyelenggaraan pemerintahan serta pembinaan dan pengawasan pemerintahan desa.\",\"tugas\":[\"Mengoordinasikan administrasi kependudukan dan pertanahan.\",\"Membina dan mengawasi penyelenggaraan pemerintahan desa.\",\"Menyiapkan bahan fasilitasi penyusunan produk hukum desa.\"]},{\"jabatan\":\"Kasi Ketenteraman & Ketertiban Umum\",\"ringkasan\":\"Melaksanakan koordinasi penyelenggaraan ketenteraman, ketertiban umum, dan penegakan peraturan daerah.\",\"tugas\":[\"Mengoordinasikan penyelenggaraan ketenteraman dan ketertiban umum.\",\"Berkoordinasi dengan aparat keamanan dalam pembinaan ketertiban masyarakat.\",\"Memfasilitasi penanganan bencana dan kesiapsiagaan di wilayah kecamatan.\"]},{\"jabatan\":\"Kasi Pemberdayaan Masyarakat\",\"ringkasan\":\"Melaksanakan koordinasi kegiatan pemberdayaan masyarakat dan pembangunan di wilayah kecamatan.\",\"tugas\":[\"Mengoordinasikan pembangunan sarana prasarana dan pengembangan ekonomi masyarakat.\",\"Memfasilitasi musyawarah perencanaan pembangunan tingkat kecamatan.\",\"Melaksanakan pemberdayaan masyarakat di bidang sosial, budaya, dan keagamaan.\"]},{\"jabatan\":\"Kasi Pelayanan Umum\",\"ringkasan\":\"Menyelenggarakan pelayanan administrasi terpadu kecamatan (PATEN) kepada masyarakat.\",\"tugas\":[\"Memberikan pelayanan perizinan dan nonperizinan sesuai kewenangan yang dilimpahkan.\",\"Menyediakan informasi persyaratan, alur, dan waktu penyelesaian layanan.\",\"Menindaklanjuti pengaduan masyarakat atas mutu pelayanan.\"]}]},\"ppid\":{\"profil\":\"PPID (Pejabat Pengelola Informasi dan Dokumentasi) Kecamatan Jenar bertanggung jawab menyediakan, menyimpan, mendokumentasikan, dan melayani permintaan informasi publik. PPID hadir untuk mewujudkan penyelenggaraan pemerintahan kecamatan yang terbuka, transparan, dan akuntabel sesuai amanat Undang-Undang Keterbukaan Informasi Publik.\",\"struktur\":[{\"jabatan\":\"Pembina / Atasan PPID\",\"keterangan\":\"Camat Jenar\"},{\"jabatan\":\"Ketua PPID Pembantu\",\"keterangan\":\"Sekretaris Kecamatan\"},{\"jabatan\":\"Bidang Pelayanan Informasi\",\"keterangan\":\"Melayani permohonan dan penyediaan informasi publik.\"},{\"jabatan\":\"Bidang Pengolahan Data & Dokumentasi\",\"keterangan\":\"Menghimpun, mengolah, dan mendokumentasikan informasi.\"},{\"jabatan\":\"Bidang Penyelesaian Sengketa\",\"keterangan\":\"Menangani keberatan dan sengketa informasi publik.\"}],\"tugas\":[\"Menyediakan dan memberikan pelayanan informasi publik kepada masyarakat.\",\"Mengumpulkan, mengklasifikasikan, dan mendokumentasikan informasi publik.\",\"Menyimpan dan mengamankan informasi serta dokumentasi kecamatan.\",\"Menyelesaikan permohonan, keberatan, dan sengketa informasi publik.\",\"Mengembangkan sistem penyediaan layanan informasi yang mudah diakses.\"],\"dasarHukum\":[\"Undang-Undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik.\",\"Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah.\",\"Peraturan Pemerintah Nomor 61 Tahun 2010 tentang Pelaksanaan Undang-Undang Keterbukaan Informasi Publik.\",\"Peraturan Pemerintah Nomor 17 Tahun 2018 tentang Kecamatan.\",\"Peraturan Komisi Informasi Nomor 1 Tahun 2021 tentang Standar Layanan Informasi Publik.\"],\"dataInformasi\":[{\"judul\":\"Informasi Berkala\",\"deskripsi\":\"Informasi yang wajib disediakan dan diumumkan secara berkala, seperti profil kecamatan dan laporan kinerja.\"},{\"judul\":\"Informasi Serta Merta\",\"deskripsi\":\"Informasi yang dapat mengancam hajat hidup orang banyak dan ketertiban umum, diumumkan tanpa penundaan.\"},{\"judul\":\"Informasi Setiap Saat\",\"deskripsi\":\"Informasi yang wajib tersedia dan dapat diakses masyarakat setiap saat, seperti standar pelayanan dan produk hukum.\"},{\"judul\":\"Informasi Dikecualikan\",\"deskripsi\":\"Informasi yang dikecualikan sesuai ketentuan peraturan perundang-undangan yang berlaku.\"}]},\"produkHukum\":[{\"jenis\":\"Keputusan Camat\",\"nomor\":\"1\",\"tahun\":2026,\"tentang\":\"Penetapan Standar Pelayanan Administrasi Terpadu Kecamatan\",\"href\":\"\"},{\"jenis\":\"Keputusan Camat\",\"nomor\":\"2\",\"tahun\":2026,\"tentang\":\"Pembentukan Tim Koordinasi Pembangunan Tingkat Kecamatan\",\"href\":\"\"},{\"jenis\":\"Keputusan Camat\",\"nomor\":\"3\",\"tahun\":2025,\"tentang\":\"Penetapan Pejabat Pengelola Informasi dan Dokumentasi (PPID) Pembantu\",\"href\":\"\"},{\"jenis\":\"Surat Edaran Camat\",\"nomor\":\"1\",\"tahun\":2026,\"tentang\":\"Tertib Administrasi Pelayanan Surat Keterangan di Wilayah Kecamatan\",\"href\":\"\"},{\"jenis\":\"Surat Edaran Camat\",\"nomor\":\"2\",\"tahun\":2025,\"tentang\":\"Pembinaan dan Pengawasan Penyelenggaraan Pemerintahan Desa\",\"href\":\"\"},{\"jenis\":\"Standar Operasional Prosedur\",\"nomor\":\"1\",\"tahun\":2026,\"tentang\":\"SOP Pelayanan Legalisasi dan Rekomendasi Surat\",\"href\":\"\"},{\"jenis\":\"Standar Operasional Prosedur\",\"nomor\":\"2\",\"tahun\":2026,\"tentang\":\"SOP Penanganan Pengaduan Masyarakat\",\"href\":\"\"}],\"galeri\":[{\"src\":\"/images/hero/slide-1.jpeg\",\"judul\":\"Musyawarah Tingkat Kecamatan\",\"alt\":\"Suasana musyawarah di aula Kantor Kecamatan Jenar\",\"kategori\":\"Pemerintahan\"},{\"src\":\"/images/hero/slide-2.jpeg\",\"judul\":\"Musrenbang Kecamatan\",\"alt\":\"Kegiatan musyawarah perencanaan pembangunan Kecamatan Jenar\",\"kategori\":\"Pembangunan\"},{\"src\":\"/images/hero/slide-3.jpg\",\"judul\":\"Rapat Koordinasi Aparatur\",\"alt\":\"Rapat koordinasi aparatur Kecamatan Jenar\",\"kategori\":\"Kegiatan\"},{\"src\":\"/images/hero/slide-1.jpeg\",\"judul\":\"Pelayanan Masyarakat\",\"alt\":\"Petugas melayani warga di Kantor Kecamatan Jenar\",\"kategori\":\"Pelayanan\"},{\"src\":\"/images/hero/slide-2.jpeg\",\"judul\":\"Gotong Royong Warga\",\"alt\":\"Warga bergotong royong membersihkan lingkungan\",\"kategori\":\"Sosial\"},{\"src\":\"/images/hero/slide-3.jpg\",\"judul\":\"Kegiatan Posyandu\",\"alt\":\"Kegiatan posyandu di wilayah Kecamatan Jenar\",\"kategori\":\"Kesehatan\"}],\"layananDetail\":{\"sop\":[{\"judul\":\"Datang & Ambil Antrean\",\"deskripsi\":\"Warga datang ke kantor kecamatan pada jam pelayanan dan mengambil nomor antrean di loket pelayanan.\"},{\"judul\":\"Menyerahkan Berkas\",\"deskripsi\":\"Menyerahkan berkas persyaratan sesuai jenis layanan kepada petugas untuk diperiksa kelengkapannya.\"},{\"judul\":\"Verifikasi & Proses\",\"deskripsi\":\"Petugas memverifikasi berkas dan memproses dokumen. Berkas yang lengkap diproses pada hari yang sama.\"},{\"judul\":\"Penandatanganan\",\"deskripsi\":\"Dokumen ditandatangani oleh Camat atau pejabat yang berwenang serta dibubuhi stempel.\"},{\"judul\":\"Penyerahan Dokumen\",\"deskripsi\":\"Dokumen yang telah selesai diserahkan kepada warga. Seluruh pelayanan tidak dipungut biaya.\"}],\"persyaratan\":[{\"nama\":\"Surat Pengantar KTP / Kartu Keluarga\",\"berkas\":[\"Fotokopi Kartu Keluarga\",\"Surat pengantar dari desa\",\"KTP lama (untuk perpanjangan)\"]},{\"nama\":\"Surat Keterangan Domisili\",\"berkas\":[\"Fotokopi KTP dan Kartu Keluarga\",\"Surat pengantar dari desa\",\"Pas foto (bila diperlukan)\"]},{\"nama\":\"Surat Keterangan Tidak Mampu (SKTM)\",\"berkas\":[\"Fotokopi KTP dan Kartu Keluarga\",\"Surat pengantar dari desa\",\"Data pendukung kondisi ekonomi\"]},{\"nama\":\"Surat Keterangan Usaha (SKU)\",\"berkas\":[\"Fotokopi KTP dan Kartu Keluarga\",\"Surat pengantar dari desa\",\"Keterangan jenis dan lokasi usaha\"]},{\"nama\":\"Surat Keterangan Kelahiran / Kematian\",\"berkas\":[\"Fotokopi KTP pelapor dan Kartu Keluarga\",\"Surat pengantar dari desa\",\"Surat keterangan dari bidan/rumah sakit (kelahiran)\"]}],\"maklumat\":\"Dengan ini kami menyatakan sanggup menyelenggarakan pelayanan sesuai standar pelayanan yang telah ditetapkan, dan apabila tidak menepati janji ini kami siap menerima sanksi sesuai peraturan perundang-undangan yang berlaku.\",\"maklumatPoin\":[\"Memberikan pelayanan yang mudah, cepat, tepat, dan tanpa biaya.\",\"Bersikap ramah, adil, dan tidak diskriminatif kepada seluruh warga.\",\"Menyelesaikan pengaduan masyarakat secara bertanggung jawab.\",\"Menjaga kerahasiaan data dan informasi pribadi warga.\"],\"pengadaanPoin\":[\"Pengadaan barang/jasa di lingkungan kecamatan dilaksanakan sesuai ketentuan pengadaan pemerintah dengan mengutamakan sumber daya dan tenaga kerja lokal.\",\"Proses pengadaan dilakukan secara transparan, akuntabel, dan sesuai ketentuan peraturan yang berlaku.\",\"Informasi rencana dan realisasi pengadaan diumumkan kepada masyarakat.\"]}}');

