INSERT IGNORE INTO berita (slug, title, date, category, excerpt, image, image_alt, author, body) VALUES ('musrenbang-kecamatan-2026', 'Musrenbang Kecamatan Jenar Bahas Prioritas Pembangunan 2026', '2026-06-13', 'Pembangunan', 'Pemerintah Kecamatan Jenar bersama pemerintah desa dan perwakilan warga merumuskan prioritas program pembangunan untuk tahun anggaran 2026.', '/images/hero/slide-2.jpeg', 'Warga menghadiri musyawarah perencanaan pembangunan tingkat kecamatan', 'Pemerintah Kecamatan Jenar', 'Dalam rangka menyusun arah pembangunan wilayah, Pemerintah Kecamatan Jenar menyelenggarakan Musyawarah Perencanaan Pembangunan (Musrenbang) tingkat kecamatan untuk Tahun Anggaran 2026. Forum ini menjadi ruang partisipasi warga dan pemerintah desa dalam menentukan prioritas pembangunan.\n\n## Prioritas Pembangunan\n\nBeberapa usulan prioritas yang dibahas meliputi:\n\n1. Peningkatan infrastruktur jalan penghubung antardesa dan drainase lingkungan.\n2. Penguatan sarana pelayanan publik dan fasilitas kesehatan.\n3. Pemberdayaan ekonomi masyarakat melalui UMKM dan pertanian.\n\n## Partisipasi Masyarakat\n\nMusyawarah dihadiri oleh para kepala desa se-Kecamatan Jenar, ketua RT/RW, kelompok perempuan, serta perwakilan pemuda. Seluruh usulan dicatat dan diusulkan ke tingkat kabupaten sebagai bahan penyusunan rencana kerja dan anggaran daerah.\n\nDengan perencanaan yang partisipatif, diharapkan program pembangunan yang dijalankan benar-benar menjawab kebutuhan masyarakat di wilayah Kecamatan Jenar.');
INSERT IGNORE INTO berita (slug, title, date, category, excerpt, image, image_alt, author, body) VALUES ('pembinaan-penyelenggaraan-pemerintahan-desa', 'Kecamatan Jenar Gelar Pembinaan Penyelenggaraan Pemerintahan Desa', '2026-06-13', 'Pemerintahan', 'Pemerintah Kecamatan Jenar melaksanakan pembinaan dan pengawasan penyelenggaraan pemerintahan desa agar tata kelola berjalan transparan dan akuntabel.', '/images/hero/slide-1.jpeg', 'Suasana pembinaan pemerintahan desa di aula Kantor Kecamatan Jenar', 'Pemerintah Kecamatan Jenar', 'Pemerintah Kecamatan Jenar menggelar kegiatan pembinaan dan pengawasan penyelenggaraan pemerintahan desa. Kegiatan ini dihadiri oleh Camat, aparatur kecamatan, para kepala desa, serta perangkat desa se-Kecamatan Jenar.\n\n## Tujuan Kegiatan\n\nPembinaan ini bertujuan memastikan tata kelola pemerintahan desa berjalan sesuai ketentuan dan pelayanan kepada masyarakat berjalan optimal, dengan mengedepankan prinsip **transparan dan akuntabel**.\n\n## Poin Pembinaan\n\nBeberapa materi utama yang disampaikan dalam kegiatan:\n\n- Tertib administrasi pemerintahan dan kearsipan desa.\n- Peningkatan mutu pelayanan administrasi kepada warga.\n- Sinergi program pembangunan desa dengan prioritas kecamatan dan kabupaten.\n\nCamat Jenar menekankan bahwa pembinaan dilaksanakan secara berkelanjutan sesuai kewenangan kecamatan dalam membina dan mengawasi penyelenggaraan pemerintahan desa.\n\n> \"Pelayanan yang baik di desa adalah wajah pelayanan pemerintah yang paling dekat dengan masyarakat.\"\n\nMasyarakat diharapkan turut berperan aktif mengawasi kualitas pelayanan demi terwujudnya pemerintahan yang bersih dan melayani.');
INSERT IGNORE INTO berita (slug, title, date, category, excerpt, image, image_alt, author, body) VALUES ('posyandu-balita-sehat-jenar', 'Kegiatan Posyandu Dukung Balita Sehat di Kecamatan Jenar', '2026-05-20', 'Kesehatan', 'Posyandu rutin di wilayah Kecamatan Jenar memberikan pelayanan penimbangan, imunisasi, dan penyuluhan gizi untuk mendukung tumbuh kembang balita.', '/images/hero/slide-1.jpeg', 'Kegiatan posyandu balita di wilayah Kecamatan Jenar', 'Pemerintah Kecamatan Jenar', 'Posyandu di wilayah Kecamatan Jenar kembali menyelenggarakan kegiatan rutin bulanan sebagai bentuk perhatian terhadap kesehatan ibu dan anak. Kegiatan ini melibatkan kader posyandu, bidan desa, puskesmas, serta dukungan Pemerintah Kecamatan Jenar.\n\n## Layanan yang Diberikan\n\nDalam kegiatan posyandu, warga memperoleh sejumlah layanan kesehatan dasar:\n\n- Penimbangan berat badan dan pengukuran tinggi badan balita.\n- Pemberian imunisasi dan vitamin.\n- Penyuluhan gizi serta pemberian makanan tambahan.\n\n## Pencegahan Stunting\n\nSalah satu fokus utama kegiatan ini adalah pemantauan tumbuh kembang balita untuk mencegah **stunting**. Kader posyandu mencatat perkembangan setiap anak dan memberikan edukasi kepada orang tua mengenai pola asuh dan gizi seimbang.\n\nPemerintah Kecamatan Jenar mengajak seluruh orang tua untuk aktif membawa balitanya ke posyandu setiap bulan demi memastikan tumbuh kembang anak berjalan optimal.');
INSERT IGNORE INTO berita (slug, title, date, category, excerpt, image, image_alt, author, body) VALUES ('rakor-agenda-strategis-awal-tahun', 'Rakor Kecamatan Jenar Bahas Agenda Strategis Awal Tahun', '2026-01-13', 'Kegiatan', 'Rapat koordinasi aparatur kecamatan membahas agenda strategis, pelayanan publik, dan evaluasi program di awal tahun anggaran.', '/images/hero/slide-3.jpg', 'Rapat koordinasi aparatur Kecamatan Jenar', 'Pemerintah Kecamatan Jenar', 'Mengawali tahun anggaran, Pemerintah Kecamatan Jenar menggelar Rapat Koordinasi (Rakor) bersama seluruh aparatur kecamatan dan para kepala desa. Rakor ini menjadi forum evaluasi sekaligus penyusunan agenda strategis untuk satu tahun ke depan.\n\n## Poin Pembahasan\n\nAgenda utama yang dibahas dalam rapat koordinasi antara lain:\n\n- Evaluasi capaian program tahun sebelumnya.\n- Penyusunan rencana kerja dan target pelayanan publik.\n- Peningkatan kualitas pelayanan administrasi terpadu kecamatan kepada warga.\n\n## Komitmen Pelayanan\n\nCamat mengajak seluruh aparatur untuk meningkatkan disiplin dan kualitas pelayanan sesuai slogan **\"Pelayanan Umum Gratis\"**. Setiap pejabat diminta memahami tugas pokok dan fungsinya masing-masing.\n\nRakor ditutup dengan penetapan jadwal kegiatan kecamatan serta komitmen bersama untuk mewujudkan pelayanan yang prima dan transparan.');
